import {
	Component,
	Element,
	Event,
	EventEmitter,
	Prop,
	Watch,
	h,
} from "@stencil/core";
import { debounce } from "../../utils/function-helper";

/**
 * @since 2.0
 * @status stable
 */

@Component({
	tag: "hbr-resize-observer",
	styleUrl: "resize-observer.scss",
	shadow: true,
})
export class ResizeObserverUtility {
	resizeObserver: ResizeObserver;
	observedElement: HTMLElement = null;
	anchorRef: HTMLElement | null = null;

	@Element() host: HTMLHbrResizeObserverElement;

	/** The element that is being observed. */
	@Prop() anchor: HTMLElement | string;

	/** If true, the resize observer will observe the children of the slot. */
	@Prop({ reflect: true }) observe = true;

	/** An optional element to add classes to when a breakpoint is active. */
	@Prop({ reflect: false }) subscriber: HTMLElement;

	/** If true, responsive classes will be added to observed elements*/
	@Prop({ reflect: true }) responsive = false;

	/** The breakpoints to observe. */
	@Prop({ reflect: false }) breakpoints = [768, 960, 1440];

	/** Debouncing the resize event. */
	@Prop({ reflect: true }) debounce = 0;

	/** The labels for each breakpoint zone. length = breakpoints.length + 1 */
	@Prop({ reflect: false }) breakpointLabels = [
		"mobile",
		"tablet",
		"laptop",
		"desktop",
	];

	/** The class prefix to add to the host element when a breakpoint is active. */
	@Prop({ reflect: true }) breakpointClass = "hbr-css__breakpoint";

	/** Emitted when the element is resized. */
	@Event({ eventName: "hbr-resize" }) hbrResize: EventEmitter;

	constructor() {
		this.handleResize = this.handleResize.bind(this);
	}

	connectedCallback() {
		if (this.debounce) {
			this.handleResize = debounce(this.handleResize, this.debounce);
		}
		this.resizeObserver = new ResizeObserver((entries) => {
			this.handleResize(entries[0]);
		});
		this.updateObserver = this.updateObserver.bind(this);
	}

	disconnectedCallback() {
		this.resizeObserver.disconnect();
	}

	componentDidLoad() {
		this.handleAnchorChange();
	}

	@Watch("anchor")
	handleAnchorChange() {
		if (this.anchor && typeof this.anchor === "string") {
			// Locate the anchor by selector
			const root = this.host.getRootNode() as Document | ShadowRoot;
			this.anchorRef = root.querySelector(this.anchor);
		} else if (this.anchor instanceof HTMLElement) {
			// Use the anchor's reference
			this.anchorRef = this.anchor as HTMLElement;
		}

		if (this.anchorRef) {
			this.updateObserver();
		}
	}

	handleResize(entry) {
		if (!entry) return;
		let width: number;
		let height: number;
		if (entry.contentBoxSize) {
			// Firefox implements `contentBoxSize` as a single content rect, rather than an array
			const { inlineSize, blockSize } = Array.isArray(entry.contentBoxSize)
				? entry.contentBoxSize[0]
				: entry.contentBoxSize;
			width = inlineSize;
			height = blockSize;
		} else {
			width = entry.contentRect.width;
			height = entry.contentRect.height;
		}

		const payload = { entry, width, height };
		const activeBreakpoint = this.updateClasses(payload);
		this.hbrResize.emit({ ...payload, activeBreakpoint });
	}

	updateObserver() {
		if (!this.observe) {
			return;
		}
		// Unwatch previous element
		if (this.observedElement) {
			this.resizeObserver?.unobserve(this.observedElement);
			this.observedElement = null;
		}
		// Watch anchor element if it exists
		if (this.anchorRef) {
			this.resizeObserver?.observe(this.anchorRef);
			this.observedElement = this.anchorRef;
			return;
		}

		// If no anchor is found, observe the first child of the slot
		const slot = this.host.shadowRoot.querySelector("slot");
		const child = slot.assignedElements({ flatten: true })[0] as HTMLElement;
		if (child) {
			this.resizeObserver?.observe(child);
			this.observedElement = child;
		}
	}

	updateClasses({ entry, width }) {
		if (!this.responsive || !entry) return;
		const prefix = this.breakpointClass;
		const breakpoints = [0, ...this.breakpoints, Infinity];
		const labels = this.breakpointLabels;
		let activeBreakpoint: string;
		// for width in boundaries, add class to host, observed element
		for (let i = 0; i < breakpoints.length - 1; i++) {
			const activeLabel = labels[i];
			const className = `${prefix}-${activeLabel}`;
			if (width > breakpoints[i] && width <= breakpoints[i + 1]) {
				this.host.classList.add(className);
				if (this.observedElement) {
					this.observedElement.classList.add(className);
				}
				if (this.subscriber instanceof HTMLElement) {
					this.subscriber.classList.add(className);
				}
				activeBreakpoint = activeLabel;
			} else {
				this.host.classList.remove(className);
				if (this.observedElement) {
					this.observedElement.classList.remove(className);
				}
				if (this.subscriber instanceof HTMLElement) {
					this.subscriber.classList.remove(className);
				}
			}
		}
		return activeBreakpoint;
	}

	render() {
		return <slot onSlotchange={this.updateObserver} />;
	}
}
